import{_ as e,o as s,c as t,a0 as o}from"./chunks/framework.BFLrGO6w.js";const u=JSON.parse('{"title":"計算公式說明","description":"","frontmatter":{},"headers":[],"relativePath":"formulas-qa.md","filePath":"formulas-qa.md"}'),i={name:"formulas-qa.md"};function n(p,a,l,d,c,r){return s(),t("div",null,[...a[0]||(a[0]=[o(`<h1 id="計算公式說明" tabindex="-1">計算公式說明 <a class="header-anchor" href="#計算公式說明" aria-label="Permalink to &quot;計算公式說明&quot;">​</a></h1><p>這份文件整理本專案所有指標的計算公式、資料來源與已知限制。 想知道「某個數字怎麼算出來的」，先查這裡。</p><p>實作位置以 <code>src/parser/</code> 為準。</p><hr><h2 id="傷害公式" tabindex="-1">傷害公式 <a class="header-anchor" href="#傷害公式" aria-label="Permalink to &quot;傷害公式&quot;">​</a></h2><h3 id="dps" tabindex="-1">DPS <a class="header-anchor" href="#dps" aria-label="Permalink to &quot;DPS&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DPS = 有效傷害 / 戰鬥秒數</span></span>
<span class="line"><span>戰鬥秒數 = pull end - pull start</span></span></code></pre></div><p>Limit Break 若技能名稱或 ability ID 在 <code>limitBreak.ts</code> 的辨識清單內，會獨立成 <code>Limit Break</code> 傷害列，不掛在施放玩家身上；總傷害仍包含 Limit Break。目前清單只收錄已驗證的 LB（<code>生者必滅</code> / <code>1EB5</code>），未收錄的 LB 會被歸到施放玩家的 DPS。</p><p>實作：<code>report/metrics.ts</code> 的 <code>toActorMetrics</code>。</p><h3 id="有效傷害-overkill-排除" tabindex="-1">有效傷害（overkill 排除） <a class="header-anchor" href="#有效傷害-overkill-排除" aria-label="Permalink to &quot;有效傷害（overkill 排除）&quot;">​</a></h3><p>對齊 FFLogs 的 effective damage 口徑：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>有效傷害 = min(原始傷害, 目標當下剩餘 HP)</span></span></code></pre></div><p>超過目標剩餘血量的部分（overkill，殺敵瞬間的溢出傷害）不計入。 目標 HP 來自 log line 的 HP 快照（action line 為 <code>fields[24]/[25]</code>、DoT tick 為 <code>fields[7]/[8]</code>，即被 tick 實體的 HP），缺漏時 fallback 到 HP cache。</p><p><strong>限制</strong>：同一 server frame 的多筆命中共用同一 HP 快照，overkill 是估算而非精確值；快照缺漏或為 0 時不裁切，避免誤刪整筆傷害。</p><p>實作：<code>report/accumulator.ts</code> 的 <code>toEffectiveDamage</code>。</p><h3 id="rdps" tabindex="-1">rDPS* <a class="header-anchor" href="#rdps" aria-label="Permalink to &quot;rDPS*&quot;">​</a></h3><p>與 FFLogs 的 rDPS 概念相同、精度不同，所以標了 <code>*</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rDPS* = (個人有效傷害 - 吃到的外部 raid buff 收益 + 自己提供給隊友的 raid buff 收益) / 戰鬥秒數</span></span></code></pre></div><p>buff 收益估算：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基準傷害 = 實際傷害 / 所有生效 buff 的總倍率</span></span>
<span class="line"><span>額外傷害 = 實際傷害 - 基準傷害</span></span>
<span class="line"><span>多 buff 疊加時，額外傷害依各 buff 的增傷權重 (倍率-1) 拆分給提供者</span></span></code></pre></div><p><strong>與 FFLogs 的差距</strong>：只收錄已驗證的 raid buff metadata；Crit/DH 類 buff（連環計、戰鬥連禱）用保守期望值常數（每 1% crit rate ≈ 0.5% 增傷、每 1% DH rate ≈ 0.25% 增傷），不是依玩家副屬性與事件 crit/DH portion 精算。連環計 metadata 已收錄，但它是套在敵人身上的 target debuff，目前 target-debuff 型 attribution 仍在 <code>doc/fflogs-rdps-validation-plan.md</code> 的 M3 跟進。</p><p>實作：<code>report/rdps.ts</code> 的 <code>estimateRaidBuffContributions</code>。</p><h3 id="dot-的-buff-歸因-snapshot" tabindex="-1">DoT 的 buff 歸因（snapshot） <a class="header-anchor" href="#dot-的-buff-歸因-snapshot" aria-label="Permalink to &quot;DoT 的 buff 歸因（snapshot）&quot;">​</a></h3><p>DoT tick 的 buff 歸因用<strong>狀態施加當下</strong>（snapshot），不是 tick 發生時間——符合 FFXIV 的 DoT snapshot 機制：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DoT tick 的歸因時間 = 該 DoT 狀態最後一次施加的時間（snapshotOffsetSeconds）</span></span>
<span class="line"><span>直接傷害的歸因時間 = 事件發生時間</span></span></code></pre></div><p>所以在 raid buff 視窗內上的 DoT，buff 結束後的 tick 仍算進 buff 貢獻。</p><p><strong>限制</strong>：合併 tick（effectId 0）用「同來源、同目標」的作用中狀態回推，可能配到同來源的非 DoT debuff（如牽制），owner 正確但 snapshot 時間可能取到鄰近狀態。</p><p>實作：<code>report/accumulator.ts</code>（addTickReportEvent）＋ <code>report/rdps.ts</code>。</p><h3 id="boss-add-傷害分類" tabindex="-1">Boss / add 傷害分類 <a class="header-anchor" href="#boss-add-傷害分類" aria-label="Permalink to &quot;Boss / add 傷害分類&quot;">​</a></h3><p>沒有 encounter 資料庫，用 HP heuristic：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>boss 候選 = 目標最大 HP ≥ max(100,000, 玩家最大 HP × 8)</span></span></code></pre></div><p>再依 primary target、BNpc 資訊細分 boss / add / object / pet。分類結果影響 <code>bossDamage</code> / <code>addDamage</code> 等統計，不影響總傷害。</p><p>實作：<code>targetClassification.ts</code>、<code>pull/rules.ts</code> 的 <code>isPrimaryTargetCandidate</code>。</p><hr><h2 id="crit-direct-hit" tabindex="-1">Crit / Direct Hit <a class="header-anchor" href="#crit-direct-hit" aria-label="Permalink to &quot;Crit / Direct Hit&quot;">​</a></h2><h3 id="crit-dh-cdh" tabindex="-1">Crit / DH / CDH <a class="header-anchor" href="#crit-dh-cdh" aria-label="Permalink to &quot;Crit / DH / CDH&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Crit% = crit hits / hits</span></span>
<span class="line"><span>DH%   = direct hits / hits</span></span>
<span class="line"><span>CDH%  = 同時爆擊且直擊的 hits / hits</span></span></code></pre></div><p>crit/DH 從 action effect flags 讀取（bit <code>0x2000</code> = crit、<code>0x4000</code> = direct hit）。</p><p><strong>限制</strong>：DoT tick（line 24）沒有 flags，<strong>計入分母但一律視為非爆擊</strong>，所以 DoT 重職業的顯示值會比實際爆擊率低。</p><p>實作：<code>actionEffect.ts</code>（flags 解析）、<code>report/metrics.ts</code>（比率計算）。</p><hr><h2 id="治療公式" tabindex="-1">治療公式 <a class="header-anchor" href="#治療公式" aria-label="Permalink to &quot;治療公式&quot;">​</a></h2><p>網站主治療指標優先採 FFLogs healing category 概念：有效 direct heal 與實際 absorb 都算 healing，overheal 不算 HPS。ACT overlay 的 raw <code>Healed</code> 口徑只保留在對帳工具。</p><h3 id="戰鬥摘要" tabindex="-1">戰鬥摘要 <a class="header-anchor" href="#戰鬥摘要" aria-label="Permalink to &quot;戰鬥摘要&quot;">​</a></h3><p>摘要卡片的治療數字來自整場 pull 彙總：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>有效治療 = sum(玩家有效治療)</span></span>
<span class="line"><span>原始治療 = sum(玩家原始治療)</span></span>
<span class="line"><span>過度治療 = 原始治療 - 有效治療</span></span>
<span class="line"><span>戰鬥摘要過治% = 過度治療 / 原始治療</span></span></code></pre></div><p>實作：<code>pullSummary.ts</code> 的 <code>overhealPercent</code>。</p><h3 id="治療表-hps-目前網站口徑" tabindex="-1">治療表 HPS（目前網站口徑） <a class="header-anchor" href="#治療表-hps-目前網站口徑" aria-label="Permalink to &quot;治療表 HPS（目前網站口徑）&quot;">​</a></h3><p>網站主表的 HPS 欄：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HPS = (有效治療 + 有效護盾(估)) / pull duration seconds</span></span></code></pre></div><p>護盾只有在被傷害實際吸收後才算有效；施放後仍剩餘、未被打掉的盾不進 HPS。即 <code>有效治療</code> 欄位的「直接治療 + 已耗盾」除以戰鬥秒數。</p><p>網站另顯示 FFLogs 概念的本地估算 <code>rHPS*</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>受治療增益額外量 = effective heal - effective heal / 所有外部受治療倍率乘積</span></span>
<span class="line"><span>rHPS* = (有效治療 + 已耗盾 + 增益提供量 - 外部增益接受量) / pull duration seconds</span></span></code></pre></div><p>目前已驗證並納入：<code>鐵壁</code>（15%）、<code>戰慄</code>（20%）、<code>生命回生法</code>（10%）。只重新歸因已發生的有效治療，不把 overheal、未消耗護盾或無法歸屬的 HoT 搬移。全隊增益提供量與接受量守恆，因此團隊 HPS 與團隊 rHPS* 總和相同。星號表示 healing buff metadata 尚未完整，不能宣稱等同 FFLogs rHPS。</p><p>FFLogs 對帳採 healing 頁的 <code>options=0</code>：包含 effective healing 與 absorbs，但關閉 mitigation。FFLogs 預設頁面會再把 mitigation 算入，不能直接拿預設總數比較網站主表。</p><p>ACT overlay 對帳工具仍按截圖欄位計算：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Overlay Healed = Eff.Heal + OverHeal + D.Shield</span></span>
<span class="line"><span>               = 原始治療 + D.Shield</span></span></code></pre></div><p><code>pull duration seconds</code> 是網站主表的戰鬥秒數，也就是 <code>pull end - pull start</code>。overlay 對帳工具為了比對截圖，會另外使用 active damage duration；那是對帳工具口徑，不是目前網站主表 HPS 分母。</p><h3 id="治療表欄位" tabindex="-1">治療表欄位 <a class="header-anchor" href="#治療表欄位" aria-label="Permalink to &quot;治療表欄位&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>有效治療 = min(原始治療量, 目標最大 HP - 目標當前 HP)</span></span>
<span class="line"><span>有效治療（主表） = 有效直接治療 + 已被傷害消耗的有效護盾(估)</span></span>
<span class="line"><span>原始治療 = heal / HoT effect 的 raw amount</span></span>
<span class="line"><span>過度治療 = 原始治療 - 有效治療</span></span>
<span class="line"><span>治療表過治% = 過度治療 / 原始治療</span></span></code></pre></div><p>同一 server frame 多筆治療可能共用相同的治療前 HP snapshot。相同目標、相同 HP snapshot 且相距不超過 250ms 時，共用同一份缺血量上限並依 log 順序分配，避免每筆治療都重複吃滿同一個 missing HP。目標再次受傷時會重置這個 healing frame。</p><p><code>NetworkDoT</code> 的 <code>HoT effectId=0</code> 是合併 tick，不可把封包 source 或任意 active buff 直接當治療來源。目前只在已確認的週期治療 status 中找來源；單一來源直接歸屬，多來源依 tooltip potency 權重拆分，無候選時保留在「無法歸屬的持續治療」，不硬塞給玩家也不丟失總量。</p><p>有效護盾(估) 不是護盾產生量，也尚未等同 FFLogs 平台 absorbs，而是敵方 action 傷害或 DoT tick 打到玩家時，若能用前後 HP 差推估出實際被 shield 吃掉的傷害，且當下可歸因到單一 shield 來源玩家，才累計到 shield 來源玩家。若同一來源玩家身上同時有多個 shield status，視為同一人的 shield stack，歸給最新的 shield status；不同來源玩家的多盾重疊仍不硬分。</p><p><strong>限制</strong>：</p><ul><li>戰鬥初期 HP cache 未建立時，fallback 把原始治療全算有效 → 短 pull 的有效治療可能略偏高。</li><li>有效護盾(估) 仍未等同 FFLogs 平台 absorbs；不同來源玩家的多盾同時存在、HP 快照缺漏或無法歸因時不硬算。</li><li>致死傷害若包含 overkill，或單筆 raw damage 已超過目標最大 HP，<code>raw damage - HP loss</code> 無法證明差額是護盾吸收，因此不計有效盾；避免團滅技的數百萬溢出傷害被誤算成有效治療。</li><li>Horoscope <code>762</code> / <code>763</code> 目前作為多盾衝突 blocker，不直接把 HP loss 歸給它們；避免在證據不足時高估 AST absorbs。</li></ul><p>實作：<code>report/accumulator.ts</code> 的 <code>estimateEffectiveHealing</code> / <code>estimateEffectiveShielding</code>、<code>report/rhps.ts</code>、<code>pullSummary.ts</code> 與 <code>PlayerHealingTable.vue</code>。</p><hr><h2 id="技能施放" tabindex="-1">技能施放 <a class="header-anchor" href="#技能施放" aria-label="Permalink to &quot;技能施放&quot;">​</a></h2><h3 id="casts-cpm" tabindex="-1">Casts / CPM <a class="header-anchor" href="#casts-cpm" aria-label="Permalink to &quot;Casts / CPM&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Casts = 玩家 action 次數（含純 buff、utility、落空的施放）</span></span>
<span class="line"><span>CPM = Casts / (戰鬥秒數 / 60)</span></span></code></pre></div><p>排除：自動攻擊、DoT/HoT tick 本身。 AOE 多目標用 <code>timestamp + player + ability</code> 去重成一次施放。</p><p>實作：<code>report/accumulator.ts</code> 的 <code>addPlayerCastEvent</code>。</p><h3 id="gcd-使用率" tabindex="-1">GCD 使用率 <a class="header-anchor" href="#gcd-使用率" aria-label="Permalink to &quot;GCD 使用率&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每次已知 GCD 技能施放 → 視為一段 [施放時間, 施放時間 + recast] 的鎖定區間</span></span>
<span class="line"><span>GCD uptime% = 合併重疊區間後的總長度 / 戰鬥秒數</span></span></code></pre></div><p>只有 ability metadata 收錄的 GCD 技能會納入（recast 預設 2.5s，部分技能有特別值），未知技能不硬算。</p><p>實作：<code>pullSummary.ts</code> 的 <code>getGcdMetrics</code>。</p><hr><h2 id="威力估算" tabindex="-1">威力估算 <a class="header-anchor" href="#威力估算" aria-label="Permalink to &quot;威力估算&quot;">​</a></h2><h3 id="威力-potency-來源" tabindex="-1">威力（potency）來源 <a class="header-anchor" href="#威力-potency-來源" aria-label="Permalink to &quot;威力（potency）來源&quot;">​</a></h3><ol><li>優先用 XIVAPI action metadata 的 potency（含 description 解析）。</li><li>缺 metadata 的傷害事件，用同場次已知事件的比例推估：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>damagePerPotency = 已知事件總傷害 / 已知事件總威力</span></span>
<span class="line"><span>推估威力 = 該事件傷害 / damagePerPotency</span></span></code></pre></div><p>UI 進度條：深綠 = 直接 metadata、淺綠 = 傷害比例推估。</p><p><strong>限制</strong>：buff 期間傷害偏高會讓推估威力略偏高；傷害為 0 的事件無法推估。</p><p>實作：<code>analysis/rotationAnalyzer.ts</code> 的 <code>analyzePotency</code>。</p><h3 id="buff-期間威力-覆蓋率" tabindex="-1">Buff 期間威力 / 覆蓋率 <a class="header-anchor" href="#buff-期間威力-覆蓋率" aria-label="Permalink to &quot;Buff 期間威力 / 覆蓋率&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Buff 期間威力 = 落在任一已收錄 buff 視窗內的事件威力總和</span></span>
<span class="line"><span>Buff 覆蓋率 = Buff 期間威力 / 總威力</span></span></code></pre></div><p>buff 視窗只計已收錄的 raid buff / personal buff（3–45 秒的短效增益），排除坦姿、食物等長效狀態。</p><hr><h2 id="pull-切分與階段" tabindex="-1">Pull 切分與階段 <a class="header-anchor" href="#pull-切分與階段" aria-label="Permalink to &quot;Pull 切分與階段&quot;">​</a></h2><h3 id="pull-切分" tabindex="-1">Pull 切分 <a class="header-anchor" href="#pull-切分" aria-label="Permalink to &quot;Pull 切分&quot;">​</a></h3><p>三層 inactivity 門檻（預設 <code>inactivityGapSeconds</code> = 45 秒，可用 <code>PULL_GAP_SECONDS</code> 環境變數調整）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>滅團中（多數玩家死亡且未復活行動）→ min(inactivityGapSeconds, 20) 秒安靜就切</span></span>
<span class="line"><span>戰鬥中（主目標存活、未滅團）      → inactivityGapSeconds × 2（預設 90 秒，容許過場動畫）</span></span>
<span class="line"><span>其他                              → inactivityGapSeconds（預設 45 秒）</span></span></code></pre></div><p>輔助規則：</p><ul><li><strong>滅團偵測</strong>：玩家死亡（line 25，含環境殺 E0000000）加入死亡名單；之後施放技能（21/22）視為已復活移除。死亡中人數 ≥ max(4, 玩家數 × 0.75) 判定滅團。</li><li><strong>起點</strong>：非玩家來源對玩家的純治療（例如開戰前仙女的 <code>仙光的擁抱</code>）不會自行開啟 pull；pull 已開始時仍會進入治療統計。</li><li><strong>終點</strong>：主目標的 action HP snapshot 或 37 / 38 / 39 actor state 顯示 HP 歸零時立即結束；line 25 death 仍是備援。王死亡後的殘留 HoT、寵物治療不延長分母。</li><li><strong>target swap 關閉</strong>：只有主目標「已死亡」後出現新的大血量目標才切新 pull；主目標活著時的新大目標視為同場戰鬥的階段角色或 add。</li><li><strong>主目標升級</strong>：血量 ≥ 現任主目標 1.2 倍的新形態會接手主目標身分（例如究極武器最終階段），pull 名稱才會對到玩家認知的 boss。</li></ul><p>實作：<code>pull/rules.ts</code>、<code>detectPulls.ts</code>。</p><h3 id="階段切分" tabindex="-1">階段切分 <a class="header-anchor" href="#階段切分" aria-label="Permalink to &quot;階段切分&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每個大型目標（boss 級 HP）「首次被玩家攻擊」記為一個階段起點</span></span>
<span class="line"><span>階段結束 = 下一個階段的開始（最後一段到 pull 結束）</span></span></code></pre></div><p>只認玩家主動攻擊（21/22）——大血量 add 攻擊玩家不算接戰，避免妙翅、爆破岩石這類 add 被誤標成階段。同名目標重複出現（如亂流階段）不會切出新階段。</p><p>每個階段產生完整報表（<code>phaseReports[]</code>）：所有表格從逐筆事件重算，與整場用同一套公式（DPS、rDPS*、Crit、治療、承傷、死亡、Casts、GCD uptime）。</p><p><strong>限制</strong>：階段時間窗以「下一個 boss 首次被攻擊」為界，過場與中間 add 潮（亂流）會算在前一階段內。</p><p>實作：<code>detectPulls.ts</code> 的 <code>trackPhaseMarker</code>、<code>pullSummary.ts</code> 的 <code>toPhaseReport</code>。</p><h3 id="kill-wipe-判定" tabindex="-1">Kill / Wipe 判定 <a class="header-anchor" href="#kill-wipe-判定" aria-label="Permalink to &quot;Kill / Wipe 判定&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kill：勝利系統訊息（寶箱出現）或 primary target 死亡</span></span>
<span class="line"><span>wipe：死亡玩家名數 ≥ max(4, 玩家數 × 0.75)</span></span>
<span class="line"><span>其餘：unknown</span></span></code></pre></div><p>階段報表只有最後一個階段繼承整場結果（boss 在該階段倒下）。</p><p>實作：<code>pullSummary.ts</code> 的 <code>inferResult</code>。</p><hr><h2 id="做不到-不做的" tabindex="-1">做不到 / 不做的 <a class="header-anchor" href="#做不到-不做的" aria-label="Permalink to &quot;做不到 / 不做的&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指標</th><th>原因</th></tr></thead><tbody><tr><td>Parse percentile（色字）</td><td>需要 FFLogs 全站同職業/同副本分布資料庫</td></tr><tr><td>aDPS</td><td>需要 FFLogs 平台的 per-job padding buff 規則</td></tr><tr><td>精確 mitigation（減傷量）</td><td>需要技能原始威力或未減傷樣本</td></tr><tr><td>護盾量（absorb）</td><td>目前只有有效護盾(估)：由 action / DoT tick 承傷事件的 HP loss 差值推估實際吸收量，且僅在可歸因到單一 shield 來源玩家時列入；同來源多層 shield 視為 stack，不同來源多盾與缺 HP 快照不硬算。</td></tr><tr><td>機制分析</td><td>需要 encounter metadata（已移除骨架，見 git 歷史）</td></tr></tbody></table><hr><h2 id="更新原則" tabindex="-1">更新原則 <a class="header-anchor" href="#更新原則" aria-label="Permalink to &quot;更新原則&quot;">​</a></h2><p>改了任何公式：</p><ol><li>對應更新這份文件；這份文件只描述目前網站已實作並實際顯示的公式，未完成或計畫中的 FFLogs 口徑要放在 gap / plan 文件。</li><li>bump <code>parserVersion</code>（<code>src/web/storage/logStore.ts</code>），讓 IndexedDB 自動 reparse。</li><li><code>npm run parse</code> 重新產生 public data。</li><li>版本歷史記在 <code>local-parser-notes.md</code>。</li></ol>`,112)])])}const b=e(i,[["render",n]]);export{u as __pageData,b as default};
